syntax:
enum class EnumName : underlying_type {
    Option1 = value1,
    Option2 = value2,
    // ...
};

// Overload bitwise operators for enum class
inline EnumName operator|(EnumName lhs, EnumName rhs) {
    return static_cast<EnumName>(
        static_cast<std::underlying_type<EnumName>::type>(lhs) |
        static_cast<std::underlying_type<EnumName>::type>(rhs)
    );
}

// Usage: EnumName combined_flags = EnumName::Option1 | EnumName::Option2;
